SELECT a.org_role_id, a.user_id, a.org_role, a.updated_time, u.user_name, u.real_name, u.phone_no
FROM bt_org_user_role a
JOIN bt_user u ON a.user_id = u.user_id
WHERE a.status_cd = '00A'
  AND u.status_cd = '00A'
  AND a.space_id = #{query.spaceId}

  AND a.org_role = #{query.orgRole}


  AND u.real_name LIKE #{query.userName}

ORDER BY a.updated_time DESC

SELECT org_role_id, user_id, org_role
FROM bt_org_user_role
WHERE status_cd = '00A'
  AND space_id = #{spaceId}
  AND user_id = #{userId}

SELECT CASE WHEN count(*) > 0 THEN 1 ELSE 0 END AS existence
FROM bt_org_user_role
WHERE status_cd = '00A'
  AND space_id = #{spaceId}
  AND user_id = #{userId}
  AND org_role = 'admin'
